local CommonActivityBossMain = Class("CommonActivityBossMain")

function CommonActivityBossMain:__init()
	self.entryMgr = nil
	self.rankNodeEnv = nil
	self.requestSuccess = false
end

function CommonActivityBossMain:__delete()
	self.entryMgr = nil
	self.rankNodeEnv = nil
	self.controller = nil
	self.requestSuccess = nil
end

function CommonActivityBossMain:Awake()
	self:InitDataCtr()
	self.activityData = self.entryMgr:GetActivityData()
	self:InitNodeEnv()
	self:AddUIClick()
	self:FreshConsumePopup()
	self.bossTipsEvent = Events.AddListener(Constants.EventNames.CommonActivityBossHurtTipsChanged, Bind(self, self.RefreshRedPoint))
end

function CommonActivityBossMain:InitNodeEnv()
	---@type CommonRankRoot
	self.rankNodeEnv = CfUtils.GetLuaScr(self.CommonRankRoot, "Game.Behaviours.CommonRankRoot")
end

function CommonActivityBossMain:AddUIClick()
    SetButtonAction(self.BtnCheck,Bind(self,self.OnBtnCheckClick))
	SetButtonAction(self.FontStyleButton,Bind(self,self.OnBtnFontStyleClick))
	SetButtonAction(self.BtnHurtReward,Bind(self,self.OnBtnHurtRewardClick))
	SetButtonAction(self.BtnRankReward,Bind(self,self.OnBtnRankRewardClick))
	SetButtonAction(self.BtnDetails,Bind(self,self.OnBtnDropDetailClick))
end

function CommonActivityBossMain:OnFocus(focus)
	if focus then
		if isNotNull(self.entryMgr) and self.requestSuccess then
			local topGoods = self.entryMgr:GetTopGoods()
			CfUtils.RefreshTopGoods(topGoods)
		end
	end
end

function CommonActivityBossMain:OnShow()

end

function CommonActivityBossMain:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		self.entryMgr:RequestShow(Bind(self,self.RefreshShow))
		while not self.requestSuccess do
			coroutine.yield()
		end
	end))
	return coWait
end

function CommonActivityBossMain:InitDataCtr()
	if isNull(self.entryMgr) then
		if isSet(self.controller.Argument.parameters,"entryMgr") then
			self.entryMgr = self.controller.Argument.parameters.entryMgr
		end
	end
end

function CommonActivityBossMain:RefreshShow(responseData)
	self.requestSuccess = true
	self.data = responseData
	self:RefreshBgAndBossName()
	CfUtils.RefreshTopGoods({})
	self:RefreshPlayerRank()
	self:FreshRoleBuffInfo()
	self:RefreshRedPoint()
end


function CommonActivityBossMain:FreshRoleBuffInfo()
	UICommonUtils.RefreshCommonUpGroup(self.CommRoleBonusLayoutGroup,self.data.upGroup, false,{{
																							  id = self.controller.Argument.id
																						  }})
end

function CommonActivityBossMain:RefreshPlayerRank()
	self.rankNodeEnv:Refresh(self.entryMgr, self.activityData)
end

function CommonActivityBossMain:RefreshBgAndBossName()
	---@type ActivityCakeBosScheduleVo
	local scheduleVo = self.entryMgr:GetScheduleVo()
	CfUtils.FillImage(self.Bg, scheduleVo.modelId)
	
	local lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(scheduleVo.range)
	for _, line in ipairs(lineUpInfo) do
		local ids = line.wave1NpcId
		for index, id in ipairs(ids) do
			local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(id)
			if checkNumber(vo.monsterClass) == Constants.RoleClass.Boss then
				local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(vo.skinId)
				CfUtils.FillText(self.TxtName, skinVo.name)
			end
		end
	end
end

function CommonActivityBossMain:GetTimesKey()
	return string.format("COMMON_BOSS_CONSUME_%s",self.activityData.id)
end

function CommonActivityBossMain:RefreshRedPoint()
	local hasRedPoint = self.entryMgr:IsHaveBossRedPoint()
	CfUtils.SetActive(self.BtnHurtReward.transform:Find("redPoint"), hasRedPoint)
end

function CommonActivityBossMain:FreshConsumePopup()
	local times = checkInt(KCookie.Get(self:GetTimesKey()))
	if times == 0 then
		times = 1
	end
	local vo = self.entryMgr:GetLevelVo()
	---@type MidFestivalBossParameterVo
	local parametersVo =  self.entryMgr:GetBossParametersVo(18)
	self.times = times
	GameUtils.FillConsumePopUp(self.AlignNode,vo,parametersVo,self.times,function(_times)
		self.times = _times
	end)
end


----click start--------------------
function CommonActivityBossMain:OnBtnCheckClick()
	---@type ActivityCakeBosScheduleVo
	local scheduleVo = self.entryMgr:GetScheduleVo()
	---@type ActivityCakeBossLevelVo
	local levelVo = self.entryMgr:GetLevelVo()
	CfUtils.DialogOpen(Constants.UITypeIds.CommonBossDetailsDialog, { planVo = scheduleVo, questVo = levelVo }, { { id = self.controller.Argument.id } })
end

function CommonActivityBossMain:OnBtnFontStyleClick()
	---@type PlayerComponent
	local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
	local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
	local endTime = checkNumber(self.activityData.endTime)
	local leftTime = endTime - curDate
	if leftTime <= 0 then
		return GameUtils.Toast(localize("活动已经结束"))
	end

	---@type ActivityCakeBosScheduleVo
	local scheduleVo = self.entryMgr:GetScheduleVo()
	KCookie.Set(self:GetTimesKey(), checkInt(self.times))
	CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamChoose, { activityUuid = self.activityData.id,
																levelId = scheduleVo.range, upBuffData = self:GetUpBuffData(),upGroup = self.data.upGroup }, { { id = self.controller.Argument.id } })
end

function CommonActivityBossMain:GetUpBuffData()
	local data = {}
	---@type CardComponent
	local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
	for i, v in ipairs(self.data.upGroup) do
		local hasCard = cardComp:IsHasCard(v.refId)
		local tempData = {}
		tempData.refId = v.refId
		tempData.type = v.type
		local index = 1
		if hasCard then
			local cardDojo = cardComp:GetCardByConfId(v.refId)
			local star = cardDojo.star
			index = star + 1
		
		end
		tempData.commonAddId = v.additions[index].commonAddId
		table.insert(data,tempData)
	end
	return data
end

function CommonActivityBossMain:OnBtnHurtRewardClick()
	CfUtils.DialogOpen(Constants.UITypeIds.CommonActivityBossDamageBonusDialog,  { entryMgr = self.entryMgr})
end

function CommonActivityBossMain:OnBtnRankRewardClick()
	CfUtils.DialogOpen(Constants.UITypeIds.CommonActivityBossRankRewardDialog, {
		rankType = checkNumber(self.rankNodeEnv.rankType), entryMgr = self.entryMgr
	})
end

function CommonActivityBossMain:OnBtnDropDetailClick()
	---@type ActivityCakeBossLevelVo
	local levelVo = self.entryMgr:GetLevelVo()
	UIModule.OpenDialog({ id = Constants.UITypeIds.CommonActivityBossDropMessagePopUp, parameters = { data = self.data.showRewards, desc = levelVo.desc } })
end

----click end----------------------
function CommonActivityBossMain:OnFinalize()
	if isNotNull(self.bossTipsEvent) then
		Events.RemoveListener(Constants.EventNames.CommonActivityBossHurtTipsChanged, self.bossTipsEvent)
		self.bossTipsEvent = nil
	end
	
	self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end


return CommonActivityBossMain